//! Integration tests: golden-file corpus + chunked/hyperslab reading.
//!
//! The fixtures in `tests/samples/` are generated by `tests/gen_samples.py`
//! (a standalone byte-builder, no netCDF4 dependency), so the assertions here
//! independently validate both the writer-shaped bytes and the parser.

use std::path::PathBuf;

use tpt_io_core::{Reader, Validator};
use tpt_io_netcdf::header::{NcType, NetCdf};
use tpt_io_netcdf::parser::{NetCdfReader, NetCdfValidator};
use tpt_io_netcdf::writer::round_trip;

fn sample(name: &str) -> Vec<u8> {
    let mut p = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    p.push("tests");
    p.push("samples");
    p.push(name);
    std::fs::read(&p).unwrap_or_else(|e| panic!("failed to read {}: {e}", p.display()))
}

#[test]
fn golden_example_metadata() {
    let bytes = sample("example.nc");
    let reader = NetCdfReader::new();
    let nc: NetCdf = reader.parse(&bytes).expect("parse example.nc");

    assert_eq!(nc.version, 1);
    assert_eq!(nc.dims.len(), 3);
    assert_eq!(nc.dims[0].name, "time");
    assert_eq!(nc.dims[0].len, 2);
    assert_eq!(nc.dims[1].name, "lat");
    assert_eq!(nc.dims[1].len, 3);
    assert_eq!(nc.dims[2].name, "lon");
    assert_eq!(nc.dims[2].len, 4);

    // Coordinate variables: those sharing a name with a dimension.
    let coords: Vec<&str> = nc.coordinate_variables().iter().map(|v| v.name.as_str()).collect();
    assert_eq!(coords, ["time", "lat", "lon"]);

    // Global attributes parsed as raw Attrs.
    let title = nc.global_attrs.iter().find(|a| a.name == "title").unwrap();
    assert_eq!(title.nc_type, NcType::Char);
    assert_eq!(title.value, b"test");

    assert!(NetCdfValidator::new().validate_syntactic(&nc).is_ok());
    assert!(NetCdfValidator::new().validate_semantic(&nc).is_ok());
}

#[test]
fn golden_example_hyperslab() {
    let bytes = sample("example.nc");
    let nc = NetCdfReader::new().parse(&bytes).unwrap();
    let temp = nc.var("temp").unwrap();

    // Full slab equals the 24 values written by the generator:
    // temp[t, la, lo] = t*100 + la*10 + lo.
    let full = nc.read_hyperslab(&bytes, temp, &[0, 0, 0], &[2, 3, 4]).unwrap();
    assert_eq!(full.len(), 24);
    assert_eq!(full[0], 0.0);
    assert_eq!(full[1], 1.0);
    assert_eq!(full[3], 3.0);
    assert_eq!(full[4], 10.0);
    assert_eq!(full[23], 123.0);

    // A single record slice temp[1, :, :] (last dim fastest).
    let slab = nc.read_hyperslab(&bytes, temp, &[1, 0, 0], &[1, 3, 4]).unwrap();
    assert_eq!(
        slab,
        vec![100.0, 101.0, 102.0, 103.0, 110.0, 111.0, 112.0, 113.0, 120.0, 121.0, 122.0, 123.0]
    );

    // A lat/long cross-section at t=0, la=1.
    let cross = nc.read_hyperslab(&bytes, temp, &[0, 1, 0], &[1, 1, 4]).unwrap();
    assert_eq!(cross, vec![10.0, 11.0, 12.0, 13.0]);

    // Out-of-bounds slab is rejected, not panicked.
    assert!(nc.read_hyperslab(&bytes, temp, &[0, 0, 0], &[3, 3, 4]).is_err());
}

#[test]
fn golden_record_metadata_and_read() {
    let bytes = sample("record.nc");
    let nc = NetCdfReader::new().parse(&bytes).unwrap();

    let time = nc.dim("time").unwrap();
    assert!(time.unlimited, "time must be the unlimited (record) dimension");
    assert_eq!(time.len, 2); // current record count from numrecs

    let temp = nc.var("temp").unwrap();
    assert!(nc.is_record_var(temp), "temp is a record variable");

    // Record read: temp[r, i] = r*10 + i (across 2 records x 3 lats).
    let all = nc.read_hyperslab(&bytes, temp, &[0, 0], &[2, 3]).unwrap();
    assert_eq!(all, vec![0.0, 1.0, 2.0, 10.0, 11.0, 12.0]);

    // Single record.
    let rec0 = nc.read_hyperslab(&bytes, temp, &[0, 0], &[1, 3]).unwrap();
    assert_eq!(rec0, vec![0.0, 1.0, 2.0]);

    // var_data is rejected for interleaved record variables.
    assert!(nc.var_data(&bytes, temp).is_err());
}

#[test]
fn header_round_trip_stable() {
    let bytes = sample("example.nc");
    let nc = NetCdfReader::new().parse(&bytes).unwrap();
    let rt = round_trip(&nc).expect("round trip");
    assert_eq!(rt.dims, nc.dims);
    assert_eq!(rt.vars, nc.vars);
    assert_eq!(rt.global_attrs, nc.global_attrs);
}
